
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ol2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ol2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.327073589562966e+00, -4.248465638814864e+00, -4.137935973392028e+00, -3.984099740013423e+00, -3.773148211863568e+00, -3.490081198563351e+00, -3.122094597280183e+00, -2.665473299337008e+00, -2.136824153616105e+00, -1.585054333024678e+00, -1.076565420928169e+00, -7.062816779066875e-01, -5.966261841274003e-01, -5.066847405065661e-01, -3.696422201256264e-01, -2.417962659457197e-01, -1.772873944363497e-01, -2.642946023314851e-01, -9.935889378262930e-01, -8.067296366542726e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


